public class Account {
    private String id;
    private int balance;
    public Account(String id) { this.id = id; }
    public void withdraw(int amount) {
        if (amount > balance) { throw new IllegalStateException("insufficient funds"); }
        balance -= amount;
    }
    public int getBalance() { return balance; }
}

